```
const { v4: uuidv4 } = require('uuid');
const logger = require('../logger');
const AppError = require('../errors/AppError');

const errorHandler = (err, req, res, next) => {
  // Ensure we have a requestId
  const requestId = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', requestId);

  // Normalize unknown errors into AppError for downstream behavior
  let error = err;
  if (!(err instanceof AppError)) {
    // preserve original stack but convert to operational wrapper
    error = new AppError(err.message || 'Internal server error', {
      code: err.code || 'ERR_INTERNAL',
      statusCode: err.statusCode || 500,
      details: err.details || null,
      isOperational: false
    });
    error.stack = err.stack;
  }

  // Structured logging: include context but avoid leaking sensitive data
  logger.error({
    err: {
      message: error.message,
      code: error.code,
      status: error.statusCode,
      isOperational: error.isOperational,
      details: error.details,
      stack: process.env.NODE_ENV === 'production' ? undefined : error.stack
    },
    requestId,
    method: req.method,
    route: req.originalUrl,
    userId: req.user && req.user.id ? req.user.id : undefined
  }, 'Unhandled error');

  const responseBody = {
    error: {
      code: error.code,
      // In production, hide unexpected internal error messages
      message: process.env.NODE_ENV === 'production' && !error.isOperational
        ? 'Internal server error'
        : error.message,
      status: error.statusCode
    }
  };

  res.status(error.statusCode).json(responseBody);
};

module.exports = errorHandler;
```

5) Example route using asyncWrapper and AppError: routes/auth.js
```
const express = require('express');
const asyncWrapper = require('../middleware/asyncWrapper');
const AppError = require('../errors/AppError');
// hypothetical auth service
const authService = require('../services/authService');

const router = express.Router();

// POST /auth/login
router.post('/login', asyncWrapper(async (req, res) => {
  const { username, password } = req.body || {};

  if (!username || !password) {
    throw new AppError('Missing username or password', { code: 'ERR_INVALID_INPUT', statusCode: 400 });
  }

  const user = await authService.authenticate(username, password);
  if (!user) {
    throw new AppError('Invalid credentials', { code: 'ERR_AUTH_FAILED', statusCode: 401 });
  }

  res.json({ userId: user.id, token: user.token });
}));

module.exports = router;
```

6) Example payment service that calls an external API: services/paymentService.js
```
const axios = require('axios');
const AppError = require('../errors/AppError');

const PAYMENT_API_URL = process.env.PAYMENT_API_URL || 'https://payments.example.com';

async function chargePayment(payload) {
  try {
    const resp = await axios.post(`${PAYMENT_API_URL}/charge`, payload, { timeout: 5000 });
    if (resp.status !== 200) {
      throw new AppError('Payment gateway error', { code: 'ERR_PAYMENT_GATEWAY', statusCode: 502, details: { status: resp.status } });
    }
    return resp.data;
  } catch (err) {
    if (err.isAxiosError) {
      // network/timeout or non-2xx
      throw new AppError('Payment gateway unreachable', {
        code: 'ERR_PAYMENT_GATEWAY',
        statusCode: 502,
        details: { message: err.message }
      });
    }
    // rethrow AppError or convert unknowns
    if (err instanceof AppError) throw err;
    throw new AppError('Unexpected payment service error', { code: 'ERR_PAYMENT_SERVICE', statusCode: 500 });
  }
}

module.exports = { chargePayment };
```

