- tests/routes/auth.test.js
```
const request = require('supertest');
const app = require('../../app'); // update path if needed
const AppError = require('../../src/errors/AppError');

describe('POST /auth/login - edge cases & standardized error response', () => {
  test('missing credentials -> 400 JSON error response and X-Request-ID header', async () => {
    const res = await request(app)
      .post('/auth/login')
      .send({}) // missing username/password
      .expect(400);

    expect(res.headers['x-request-id']).toBeDefined();
    expect(res.body).toHaveProperty('error');
    expect(res.body.error).toMatchObject({
      code: 'ERR_INVALID_INPUT',
      status: 400
      // message present but exact wording depends on locale/env
    });
  });

  test('unexpected error -> 500 masked message in production, structured JSON', async () => {
    // Temporarily simulate an unexpected error by mocking authService.authenticate to throw
    jest.resetModules();
    const authService = require('../../src/services/authService');
    // mock authenticate to throw a raw Error
    authService.authenticate = jest.fn().mockImplementation(() => { throw new Error('DB died'); });

    const res = await request(app)
      .post('/auth/login')
      .send({ username: 'u', password: 'p' })
      .expect(500);

    expect(res.body).toHaveProperty('error');
    expect(res.body.error.code).toBeDefined();
    expect(res.headers['x-request-id']).toBeDefined();
  });
});
```
Note: adjust import path for authService to match your repo and ensure jest can mock it. If your project exports authService differently, adapt the mock.

- tests/services/paymentService.test.js
```
const nock = require('nock');
const { chargePayment } = require('../../src/services/paymentService');
const AppError = require('../../src/errors/AppError');

const PAYMENT_HOST = process.env.PAYMENT_API_URL || 'https://payments.example.com';

describe('paymentService edge cases', () => {
  afterEach(() => {
    nock.cleanAll();
  });

  test('payment gateway returns non-200 -> AppError with ERR_PAYMENT_GATEWAY', async () => {
    nock(PAYMENT_HOST)
      .post('/charge')
      .reply(502, { message: 'bad gateway' });

    await expect(chargePayment({ amount: 123 }))
      .rejects
      .toMatchObject({ code: 'ERR_PAYMENT_GATEWAY', statusCode: 502 });
  });

  test('network timeout -> AppError with ERR_PAYMENT_GATEWAY', async () => {
    nock(PAYMENT_HOST)
      .post('/charge')
      .delayConnection(6000) // longer than axios timeout in sample
      .reply(200, {});

    await expect(chargePayment({ amount: 123 }))
      .rejects
      .toMatchObject({ code: 'ERR_PAYMENT_GATEWAY' });
  });
});
```

