Great — below is a single-file, paste-ready module that contains: AppError, a pino logger, asyncWrapper, and the Express error-handling middleware. Drop it into your repo (suggested path: src/utils/errorHelpers.js or src/middleware/errorHelpers.js), run npm i pino uuid, then require and wire the middleware in app.js.

File: src/utils/errorHelpers.js
```
/**
 * Combined helpers: AppError, pino logger, asyncWrapper, and Express errorHandler
 *
 * Usage:
 *  const { AppError, asyncWrapper, errorHandler, logger } = require('./utils/errorHelpers');
 *  app.use(errorHandler); // after routes
 *
 * Requires: pino, uuid
 * Install: npm i pino uuid
 */

const pino = require('pino');
const { v4: uuidv4 } = require('uuid');

/* -------------------------
   Logger (pino wrapper)
   ------------------------- */
const logger = pino({
  level: process.env.LOG_LEVEL || 'info',
  prettyPrint: process.env.NODE_ENV !== 'production'
});

/* -------------------------
   AppError
   ------------------------- */
class AppError extends Error {
  /**
   * @param {string} message
   * @param {object} opts
   * @param {string} opts.code - machine-readable code (e.g. 'ERR_INVALID_INPUT')
   * @param {number} opts.statusCode - HTTP status
   * @param {any} opts.details - optional additional context
   * @param {boolean} opts.isOperational - whether safe to show message to user
   */
  constructor(message, { code = 'ERR_INTERNAL', statusCode = 500, details = null, isOperational = true } = {}) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.statusCode = statusCode;
    this.details = details;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

/* -------------------------
   asyncWrapper for routes
   ------------------------- */
const asyncWrapper = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* -------------------------
   Express error-handling middleware
   ------------------------- */
const errorHandler = (err, req, res, next) => {
  // Ensure we have a requestId (echo back and include in logs)
  const requestId = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', requestId);

  // Normalize unknown errors to AppError (preserve stack if present)
  let error = err;
  if (!(err instanceof AppError)) {
    error = new AppError(err.message || 'Internal server error', {
      code: err.code || 'ERR_INTERNAL',
      statusCode: err.statusCode || 500,
      details: err.details || null,
      isOperational: false
    });
    // preserve original stack for dev or detailed logs
    error.stack = err.stack;
  }

  // Structured logging without leaking secrets.
  logger.error({
    err: {
      message: error.message,
      code: error.code,
      status: error.statusCode,
      isOperational: error.isOperational,
      details: error.details,
      stack: process.env.NODE_ENV === 'production' ? undefined : error.stack
    },
    requestId,
    method: req.method,
    route: req.originalUrl,
    userId: req.user && req.user.id ? req.user.id : undefined
  }, 'Unhandled error');

  const responseBody = {
    error: {
      code: error.code,
      // Mask message for internal/non-operational errors in production
      message: process.env.NODE_ENV === 'production' && !error.isOperational
        ? 'Internal server error'
        : error.message,
      status: error.statusCode
    }
  };

  res.status(error.statusCode).json(responseBody);
};

module.exports = {
  AppError,
  asyncWrapper,
  errorHandler,
  logger
};
```

