Great — below are two ready-to-use items:

1) A Google Apps Script you can paste & run to create the Google Form (it will create the form, link it to a new spreadsheet, and add Maria Lopez as an editor). Follow the short instructions after the script.

2) A short printable flyer text (two versions: poster and small handout) you can copy/paste into a document or print. I also included quick printing/QR suggestions.

Google Apps Script (ready-to-paste)
- Steps to run:
  1. Go to https://script.google.com/ and create a new project (or open https://docs.google.com/forms, then Tools > Script editor).
  2. Replace the default code with the script below.
  3. Save, then Run the function createVolunteerForm(). The first time you run it you’ll be asked to authorize permissions.
  4. After it runs, open the script’s Logs (View > Logs) to see the form edit URL and the linked spreadsheet URL.
  5. Open the form link, review the form, tweak questions if needed, then copy the live form link and use it in your posts/flyers.

Script:
function createVolunteerForm() {
  // Create the form
  var form = FormApp.create('Northside Community Resource Fair — Volunteer Sign-Up (May 9, 2026)');
  form.setDescription('Thank you for volunteering! Event: Saturday, May 9, 2026 — 10:00 AM–2:00 PM at Maple Community Center (123 Maple St.). Organizer: Helping Hands Collective — Maria Lopez (maria@helpinghands.org, (555) 123-4567). We will confirm roles and send final check-in details by May 8.');
  form.setCollectEmail(true);
  form.setConfirmationMessage('Thanks — we received your sign-up. We’ll confirm your role/time by May 8 and send final check-in details. If urgent, contact [Your name] at [phone] or Maria Lopez at maria@helpinghands.org / (555) 123-4567.');

  // Questions
  form.addTextItem().setTitle('Full name').setRequired(true);
  form.addTextItem().setTitle('Email address').setRequired(true);
  form.addTextItem().setTitle('Phone number').setRequired(true);

  var ageItem = form.addMultipleChoiceItem();
  ageItem.setTitle('Are you 18 or over?').setRequired(true);
  ageItem.setChoices([
    ageItem.createChoice('Yes'),
    ageItem.createChoice('No (If no, minors may need a parent/guardian; we will confirm with organizers.)')
  ]);

  var rolesItem = form.addCheckboxItem();
  rolesItem.setTitle('Which role(s) would you prefer?').setRequired(true);
  rolesItem.setChoices([
    rolesItem.createChoice('Setup (approx. 8:30–10:00)'),
    rolesItem.createChoice('Check-in / Registration (approx. 9:30–12:00)'),
    rolesItem.createChoice('Info table — morning (10:00–12:00)'),
    rolesItem.createChoice('Info table — afternoon (12:00–2:00)'),
    rolesItem.createChoice('Directions / Parking guide (9:30–11:30)'),
    rolesItem.createChoice('Directions / Parking guide (11:30–2:00)'),
    rolesItem.createChoice('Teardown (1:30–3:30)'),
    rolesItem.createChoice('Other (please specify in next question)')
  ]);

  form.addTextItem().setTitle('If you selected "Other" or have role notes, please specify').setRequired(false);

  var shiftItem = form.addMultipleChoiceItem();
  shiftItem.setTitle('Preferred shift time').setRequired(true);
  shiftItem.setChoices([
    shiftItem.createChoice('8:30–11:00'),
    shiftItem.createChoice('9:30–12:00'),
    shiftItem.createChoice('11:00–2:00'),
    shiftItem.createChoice('12:00–2:30'),
    shiftItem.createChoice('I’m flexible — any time helps')
  ]);

  form.addParagraphTextItem().setTitle('Any relevant experience, certifications, or accessibility needs we should know about?').setRequired(false);

  var bringItem = form.addCheckboxItem();
  bringItem.setTitle('I can bring / lend').setRequired(false);
  bringItem.setChoices([
    bringItem.createChoice('Folding chairs'),
    bringItem.createChoice('Clipboards & pens'),
    bringItem.createChoice('Snacks/water for volunteers'),
    bringItem.createChoice('Vehicle to help move supplies'),
    bringItem.createChoice('Nothing to bring, just myself')
  ]);

  form.addParagraphTextItem().setTitle('Is there anything else we should know?').setRequired(false);

  // Create and attach a response spreadsheet
  var ss = SpreadsheetApp.create('Northside Resource Fair — Volunteer Responses (May 9 2026)');
  form.setDestination(FormApp.DestinationType.SPREADSHEET, ss.getId());

  // Add Maria as an editor so she can view responses and edit if needed
  try {
    form.addEditor('maria@helpinghands.org');
  } catch (e) {
    // If adding editor fails (e.g., permissions), an error will be shown in logs but form will still be created
    Logger.log('Could not add Maria as editor: ' + e);
  }

  // Log useful links
  Logger.log('Form edit URL: ' + form.getEditUrl());
  Logger.log('Form live URL (for sharing): ' + form.getPublishedUrl());
  Logger.log('Responses spreadsheet URL: ' + ss.getUrl());
}

